const { useState } = React;

function Counter() {
  const [count, setCount] = useState(0);

  return (
    <div>
      <p id="value">{count}</p>
      <button id="add" onClick={() => setCount((previous) => previous + 1)}>
        Add
      </button>
      <button id="reset" onClick={() => setCount(0)}>
        Reset
      </button>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<Counter />);
